<script setup lang="ts">
/**
 * ParentalControlsPage (P5-S5) — per-profile parental controls.
 *
 * Three tabbed sections mirroring the console client's ParentalControlsScreen:
 *   - Schedules: access time windows (create / edit / delete)
 *   - Tags: content rating tags (blocked / allowed)
 *   - Stream limits: max concurrent streams and bandwidth
 *
 * The profile is selected via route query `?profile=<id>`. When opened from
 * the admin users list the parent component should navigate with that query.
 */
import { ref, computed, onMounted, inject, type ComputedRef } from 'vue';
import { useRoute } from 'vue-router';
import { ApiClient } from '../api/client';
import {
  AdminUsersApi,
  RATING_LABELS,
  type AccessSchedule,
  type Profile,
  type ProfileStreamLimit,
  type ProfileTag,
} from '../api/admin/users';
import { useToastStore } from '../stores/useToastStore';
import { useMessages } from '../composables/useMessages';
import { errMessage } from '../api/errors';
import Tabs, { type TabItem } from '../components/ui/Tabs.vue';
import Button from '../components/ui/Button.vue';
import Modal from '../components/ui/Modal.vue';
import Select from '../components/ui/Select.vue';
import Input from '../components/ui/Input.vue';
import Switch from '../components/ui/Switch.vue';
import Badge from '../components/ui/Badge.vue';
import Skeleton from '../components/ui/Skeleton.vue';
import EmptyState from '../components/ui/EmptyState.vue';
import Card from '../components/ui/Card.vue';
import Icon from '../components/Icon.vue';

const route = useRoute();
const toasts = useToastStore();
// M13 option A (deferred lane 2026-11-03): every member-facing sentence this
// page renders resolves through the `parental` catalog group — the group the
// page used to duplicate inline (copywriter M5: a consumer overriding
// `parental.*` changed nothing on screen). The t() keys are type-checked
// against the catalog (a missing key is a vue-tsc error), so this is the
// fail-loud adoption the catalog's promise demands.
const { t } = useMessages();

const props = defineProps<{
  /** Inject a pre-built API client for tests; otherwise one is built from `apiBase`. */
  client?: ApiClient;
}>();

const injectedApiBase = inject<string | ComputedRef<string> | undefined>('apiBase', '');
const apiBase = computed(() =>
  typeof injectedApiBase === 'string' ? injectedApiBase : injectedApiBase?.value ?? '',
);
const api = new AdminUsersApi(
  props.client ?? new ApiClient({ baseUrl: apiBase.value }),
);

// ── Profile selection ─────────────────────────────────────────────────────────
const profiles = ref<Profile[]>([]);
/**
 * The profile id from `?profile=`, held as an opaque STRING (S209).
 *
 * `user_profiles.id` is `CHAR(36)` — a UUID — so there is no number to parse it
 * into. It was held as `number | null` until S209, which is what made the old
 * `!isNaN(Number(...))` gate look coherent while rejecting every genuine id.
 */
const selectedProfileId = ref<string | null>(null);
const loadingProfiles = ref(true);
/** Why the profile could not be identified, when it could not be (S203). */
const profilesError = ref<string | null>(null);

/**
 * The profile whose restrictions are on screen.
 *
 * Matched by STRING identity rather than `===`. `selectedProfileId` is a string
 * off the query, but the WIRE id is only as trustworthy as the driver: a numeric
 * `7` arriving where the local id is `'7'` would fail a strict compare and
 * silently drop the very profile that was just fetched by that id — reproducing
 * the "no name on screen" symptom S203 removed. `String()` on BOTH sides is what
 * makes the comparison indifferent to that, so neither call is redundant.
 */
const selectedProfile = computed(
  () => profiles.value.find((p) => String(p.id) === String(selectedProfileId.value)) ?? null,
);

/**
 * Load the profile named by `?profile=<id>` so the header can say WHOSE
 * restrictions are being edited (S203).
 *
 * Only the one profile is fetched, not the whole estate: the page is keyed by a
 * profile id, and `listProfiles` is keyed by `userId`, which this screen never
 * has.
 *
 * On failure this deliberately does NOT stay silent (the previous stub swallowed
 * everything with a `// Silently fail`). An access-control editor that cannot say
 * which child it is editing looks *identical* to one that can, so a silent failure
 * is indistinguishable from success — the admin has no way to notice they may be
 * editing the wrong child. Instead the header renders an explicit "unidentified"
 * warning carrying the id and the reason.
 *
 * It equally does NOT gate the editor. Blocking the restriction controls on a
 * cosmetic name lookup would turn a metadata outage into "nobody can tighten a
 * child's limits", which is the worse direction on this surface. Warn loudly,
 * keep working.
 */
async function loadProfiles(): Promise<void> {
  const profileId = selectedProfileId.value;
  if (!profileId) {
    profiles.value = [];
    profilesError.value = null;
    loadingProfiles.value = false;
    return;
  }
  loadingProfiles.value = true;
  profilesError.value = null;
  try {
    profiles.value = [await api.getProfile(profileId)];
  } catch (e) {
    profiles.value = [];
    profilesError.value = errMessage(e, t('parental.profileLoadError'));
  } finally {
    loadingProfiles.value = false;
  }
}

/**
 * Read the profile id out of `?profile=` (S209).
 *
 * A profile id is a `CHAR(36)` UUID — `user_profiles.id` in
 * `migrations/002_user_profiles_and_parental_controls.sql:6` — so the ONLY thing
 * this can check is that exactly one non-empty value was supplied. It must not
 * check the id's shape:
 *
 *  - It previously required `!isNaN(Number(id))`, and `Number()` of any UUID is
 *    `NaN`. The gate therefore rejected every real id and admitted only bare
 *    integers, which no profile has ever had — the page could not be opened at
 *    all. That is the defect S209 exists to remove, so re-deriving any *format*
 *    rule here would be the same mistake in a new spelling.
 *  - The server itself does not agree on a format: `AdminProfileController::get`
 *    accepts any string and 404s an unknown one, `ProfileTagController` requires
 *    only a non-empty string, while `AccessScheduleController::parseProfileId`
 *    and `StreamLimitController::parseProfileId` demand a canonical UUID. A
 *    client stricter than the LOOSEST of those would refuse ids the server would
 *    happily serve. Validation belongs at the authority; the client routes.
 *
 * A wrong id is therefore no longer silent: it reaches the server and comes back
 * 404/400, which S203's "Unidentified profile #<id>" badge renders with the
 * reason. That is strictly more informative than the blank "No profile selected"
 * empty state the numeric gate produced, and it still fails CLOSED — every write
 * path re-validates server-side, so nothing can be persisted against a bogus id.
 *
 * The one shape that must still be refused is a REPEATED `?profile=a&profile=b`,
 * which vue-router hands over as an array. There is no defensible way to choose
 * between two ids on an access-control screen, so an array is treated as "no id
 * given" rather than silently taking the first.
 */
onMounted(() => {
  const queryProfileId = route.query.profile;
  if (typeof queryProfileId === 'string' && queryProfileId.trim() !== '') {
    selectedProfileId.value = queryProfileId.trim();
  }
  void loadProfiles();
  if (selectedProfileId.value) {
    void loadSectionData(activeTab.value);
  }
});

// ── Tab state ─────────────────────────────────────────────────────────────────
type TabValue = 'schedules' | 'tags' | 'streamLimits';

const TABS: TabItem[] = [
  { value: 'schedules', label: t('parental.schedules'), icon: 'calendar' },
  { value: 'tags', label: t('parental.tags'), icon: 'bookmark' },
  { value: 'streamLimits', label: t('parental.streamLimits'), icon: 'play' },
];

const activeTab = ref<TabValue>('schedules');

// ── Schedules ─────────────────────────────────────────────────────────────────
interface ScheduleFormData {
  name: string;
  startTime: string;
  endTime: string;
  daysOfWeek: string[];
  isActive: boolean;
}

const VALID_DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'] as const;

const schedules = ref<AccessSchedule[]>([]);
const loadingSchedules = ref(false);
const schedulesError = ref<string | null>(null);
const selectedScheduleIndex = ref(0);
const showScheduleForm = ref(false);
const editingSchedule = ref<AccessSchedule | null>(null);
const scheduleForm = ref<ScheduleFormData>({
  name: '',
  startTime: '08:00',
  endTime: '22:00',
  daysOfWeek: ['mon', 'tue', 'wed', 'thu', 'fri'],
  isActive: true,
});
const formError = ref<string | null>(null);
const pendingDeleteSchedule = ref<AccessSchedule | null>(null);
const showDeleteScheduleModal = computed({
  get: () => pendingDeleteSchedule.value !== null,
  set: (val: boolean) => { if (!val) pendingDeleteSchedule.value = null; },
});

async function loadSchedules(): Promise<void> {
  if (!selectedProfileId.value) return;
  loadingSchedules.value = true;
  schedulesError.value = null;
  try {
    schedules.value = await api.profileSchedules(selectedProfileId.value);
    selectedScheduleIndex.value = Math.min(selectedScheduleIndex.value, schedules.value.length - 1);
  } catch (e) {
    schedulesError.value = errMessage(e, t('parental.loadErrorSchedules'));
  } finally {
    loadingSchedules.value = false;
  }
}

function openScheduleCreate(): void {
  editingSchedule.value = null;
  scheduleForm.value = {
    name: '',
    startTime: '08:00',
    endTime: '22:00',
    daysOfWeek: ['mon', 'tue', 'wed', 'thu', 'fri'],
    isActive: true,
  };
  formError.value = null;
  showScheduleForm.value = true;
}

function openScheduleEdit(schedule: AccessSchedule): void {
  editingSchedule.value = schedule;
  scheduleForm.value = {
    name: schedule.name,
    startTime: schedule.start_time.substring(0, 5), // HH:MM from HH:MM:SS
    endTime: schedule.end_time.substring(0, 5),
    daysOfWeek: [...schedule.days_of_week],
    isActive: schedule.is_active,
  };
  formError.value = null;
  showScheduleForm.value = true;
}

function validateScheduleForm(): string | null {
  if (!scheduleForm.value.name.trim()) return 'Name is required.';
  if (scheduleForm.value.name.length > 100) return 'Name must be 100 characters or less.';
  if (!/^\d{1,2}:\d{2}(:\d{2})?$/.test(scheduleForm.value.startTime)) {
    return 'Invalid start time. Use HH:MM or HH:MM:SS.';
  }
  if (!/^\d{1,2}:\d{2}(:\d{2})?$/.test(scheduleForm.value.endTime)) {
    return 'Invalid end time. Use HH:MM or HH:MM:SS.';
  }
  if (scheduleForm.value.daysOfWeek.length === 0) return 'At least one day is required.';
  return null;
}

/**
 * Persist the schedule form — CREATE for a new schedule, a single in-place
 * UPDATE for an existing one.
 *
 * ⚠ An edit must NEVER be a delete followed by a create (S202). It was exactly
 * that until this change, justified by an inline "no individual update endpoint"
 * that was simply untrue — `PUT .../schedules/{scheduleId}` has been served all
 * along (see {@link AdminUsersApi.updateProfileSchedule} for the route and the
 * handler). The two calls were not atomic and nothing compensated, so a create
 * that failed after the delete committed — a network blip, a validation refusal,
 * a 500 — left the profile with NO time restriction at all, while the only
 * signal was an inline message in a modal the admin can close.
 *
 * That failure direction is what makes it a defect rather than a rough edge: on
 * an access-control surface the safe direction is to leave the OLD restriction
 * standing. A failed edit here now writes nothing and destroys nothing, because
 * the single request either applies in full server-side or does not apply at all
 * — there is no half-state for the client to unwind.
 *
 * The reason `editingSchedule` is read for the id rather than the selected row:
 * it is the row the form was OPENED from, so it cannot drift if the list is
 * re-sorted or the selection moves while the modal is up.
 */
async function submitScheduleForm(): Promise<void> {
  if (!selectedProfileId.value) return;
  const error = validateScheduleForm();
  if (error) {
    formError.value = error;
    return;
  }
  try {
    if (editingSchedule.value) {
      await api.updateProfileSchedule(
        selectedProfileId.value,
        editingSchedule.value.id,
        scheduleForm.value.name.trim(),
        scheduleForm.value.startTime + ':00',
        scheduleForm.value.endTime + ':00',
        scheduleForm.value.daysOfWeek,
        scheduleForm.value.isActive,
      );
    } else {
      await api.createProfileSchedule(
        selectedProfileId.value,
        scheduleForm.value.name.trim(),
        scheduleForm.value.startTime + ':00',
        scheduleForm.value.endTime + ':00',
        scheduleForm.value.daysOfWeek,
        scheduleForm.value.isActive,
      );
    }
    toasts.success(editingSchedule.value ? t('parental.scheduleUpdated') : t('parental.scheduleCreated'));
    showScheduleForm.value = false;
    await loadSchedules();
  } catch (e) {
    formError.value = errMessage(e, t('parental.scheduleSaveError'));
  }
}

async function confirmDeleteSchedule(schedule: AccessSchedule): Promise<void> {
  if (!selectedProfileId.value) return;
  try {
    await api.deleteProfileSchedule(selectedProfileId.value, schedule.id);
    toasts.success(t('parental.scheduleDeleted'));
    pendingDeleteSchedule.value = null;
    await loadSchedules();
  } catch (e) {
    toasts.error(errMessage(e, t('parental.scheduleDeleteError')));
    pendingDeleteSchedule.value = null;
  }
}

function toggleScheduleDay(day: string): void {
  const idx = scheduleForm.value.daysOfWeek.indexOf(day);
  if (idx === -1) {
    scheduleForm.value.daysOfWeek.push(day);
  } else {
    scheduleForm.value.daysOfWeek.splice(idx, 1);
  }
}

function formatDays(days: string[]): string {
  const dayLabels: Record<string, string> = {
    mon: 'Mon',
    tue: 'Tue',
    wed: 'Wed',
    thu: 'Thu',
    fri: 'Fri',
    sat: 'Sat',
    sun: 'Sun',
  };
  return days.map((d) => dayLabels[d] ?? d).join(', ');
}

// ── Tags ───────────────────────────────────────────────────────────────────────
const TAG_TYPE_OPTIONS = [
  { value: 'blocked', label: t('parental.tagBlocked') },
  { value: 'allowed', label: t('parental.tagAllowed') },
];

const tags = ref<ProfileTag[]>([]);
const loadingTags = ref(false);
const tagsError = ref<string | null>(null);
const selectedTagIndex = ref(0);
const showTagForm = ref(false);
const tagForm = ref({ tag: '', tagType: 'blocked' as 'blocked' | 'allowed' });
const tagFormError = ref<string | null>(null);
const pendingDeleteTag = ref<ProfileTag | null>(null);
const showDeleteTagModal = computed({
  get: () => pendingDeleteTag.value !== null,
  set: (val: boolean) => { if (!val) pendingDeleteTag.value = null; },
});

async function loadTags(): Promise<void> {
  if (!selectedProfileId.value) return;
  loadingTags.value = true;
  tagsError.value = null;
  try {
    tags.value = await api.profileTags(selectedProfileId.value);
    selectedTagIndex.value = Math.min(selectedTagIndex.value, tags.value.length - 1);
  } catch (e) {
    tagsError.value = errMessage(e, t('parental.loadErrorTags'));
  } finally {
    loadingTags.value = false;
  }
}

function openTagCreate(): void {
  tagForm.value = { tag: '', tagType: 'blocked' };
  tagFormError.value = null;
  showTagForm.value = true;
}

async function submitTagForm(): Promise<void> {
  if (!selectedProfileId.value) return;
  const tag = tagForm.value.tag.trim();
  if (!tag) {
    tagFormError.value = 'Tag name is required.';
    return;
  }
  if (tag.length > 100) {
    tagFormError.value = 'Tag must be 100 characters or less.';
    return;
  }
  try {
    await api.addProfileTag(selectedProfileId.value, tag, tagForm.value.tagType);
    toasts.success(t('parental.tagAdded'));
    showTagForm.value = false;
    await loadTags();
  } catch (e) {
    tagFormError.value = errMessage(e, t('parental.tagAddError'));
  }
}

async function confirmDeleteTag(tag: ProfileTag): Promise<void> {
  if (!selectedProfileId.value) return;
  try {
    await api.deleteProfileTag(selectedProfileId.value, tag.id);
    toasts.success(t('parental.tagRemoved'));
    pendingDeleteTag.value = null;
    await loadTags();
  } catch (e) {
    toasts.error(errMessage(e, t('parental.tagRemoveError')));
    pendingDeleteTag.value = null;
  }
}

// ── Stream limits ──────────────────────────────────────────────────────────────
const streamLimits = ref<ProfileStreamLimit | null>(null);
const loadingStreamLimits = ref(false);
const streamLimitsError = ref<string | null>(null);
const showStreamLimitsForm = ref(false);
/**
 * Both fields are bound to `<Input type="number">`. For that type `Input.vue`
 * emits `Number(target.value)` when digits are typed — so whatever type these
 * are SEEDED with, they become NUMBERS the instant the user types — and emits
 * the empty STRING when the field is cleared (UI-m23: clearing means "no
 * value", never a phantom 0). They are seeded as a string
 * (`openStreamLimitsEdit` formats the bandwidth with `.toString()`) and as a
 * number, so `string | number` is the honest type for both.
 *
 * This declaration is the S201 defect made visible: the type was previously
 * written as if the seed were the only shape, which is why `.trim()` type-checked
 * and still threw at runtime.
 */
const streamLimitsForm = ref<{
  maxConcurrentStreams: string | number;
  maxTotalBandwidthKbps: string | number;
}>({ maxConcurrentStreams: 1, maxTotalBandwidthKbps: '' });
const streamLimitsFormError = ref<string | null>(null);

/**
 * Parse a `<Input type="number">` model to a whole number, tolerating the shapes
 * it legitimately arrives in: the string it was seeded with, the number
 * `Input.vue` emits once digits are typed, and the empty string it emits when
 * the field is cleared (UI-m23).
 *
 * Returns `null` for "no usable value" — blank, non-numeric, or below `min`.
 * Fractions are truncated, matching the `parseInt` this replaces.
 */
function parseNumericInput(value: string | number, min: number): number | null {
  const n = typeof value === 'number' ? value : parseInt(value.trim(), 10);
  if (!Number.isFinite(n) || n < min) return null;
  return Math.trunc(n);
}

async function loadStreamLimits(): Promise<void> {
  if (!selectedProfileId.value) return;
  loadingStreamLimits.value = true;
  streamLimitsError.value = null;
  try {
    streamLimits.value = await api.profileStreamLimits(selectedProfileId.value);
  } catch (e) {
    streamLimitsError.value = errMessage(e, t('parental.loadErrorStreamLimits'));
  } finally {
    loadingStreamLimits.value = false;
  }
}

function openStreamLimitsEdit(): void {
  streamLimitsForm.value = {
    maxConcurrentStreams: streamLimits.value?.max_concurrent_streams ?? 1,
    maxTotalBandwidthKbps: streamLimits.value?.max_total_bandwidth_kbps?.toString() ?? '',
  };
  streamLimitsFormError.value = null;
  showStreamLimitsForm.value = true;
}

/**
 * Persist the stream limits.
 *
 * ⚠ The parse and the validation both live INSIDE the `try` on purpose (S201).
 * They used to sit above it, so when the bandwidth parse threw — which it did on
 * every edit, see {@link parseNumericInput} — the TypeError escaped the handler
 * entirely: no PUT, no `streamLimitsFormError`, no toast, nothing on screen at
 * all. A silent no-op on an access-control form is worse than a visible failure,
 * so anything that can throw here must be inside the guarded region and surface
 * through the same `catch` the network errors use.
 */
async function submitStreamLimitsForm(): Promise<void> {
  if (!selectedProfileId.value) return;
  try {
    const maxStreams = parseNumericInput(streamLimitsForm.value.maxConcurrentStreams, 1);
    if (maxStreams === null) {
      streamLimitsFormError.value = 'Max concurrent streams must be at least 1.';
      return;
    }
    // A blank / sub-1 bandwidth is "no cap", not an error — the field is optional.
    const maxBandwidth = parseNumericInput(streamLimitsForm.value.maxTotalBandwidthKbps, 1);
    await api.updateProfileStreamLimits(selectedProfileId.value, maxStreams, maxBandwidth);
    toasts.success(t('parental.streamLimitsUpdated'));
    showStreamLimitsForm.value = false;
    await loadStreamLimits();
  } catch (e) {
    streamLimitsFormError.value = errMessage(e, t('parental.streamLimitsSaveError'));
  }
}

// ── Tab loading ────────────────────────────────────────────────────────────────
async function loadSectionData(tab: TabValue): Promise<void> {
  switch (tab) {
    case 'schedules':
      await loadSchedules();
      break;
    case 'tags':
      await loadTags();
      break;
    case 'streamLimits':
      await loadStreamLimits();
      break;
  }
}

function handleTabChange(tab: string): void {
  activeTab.value = tab as TabValue;
  void loadSectionData(tab as TabValue);
}

// ── Delete confirmations ───────────────────────────────────────────────────────
function askDeleteSchedule(schedule: AccessSchedule): void {
  pendingDeleteSchedule.value = schedule;
}

function askDeleteTag(tag: ProfileTag): void {
  pendingDeleteTag.value = tag;
}
</script>

<template>
  <div class="parental-page">
    <header class="parental-page__head">
      <div>
        <p class="parental-page__eyebrow">Profile Controls</p>
        <h1 class="parental-page__title">{{ t('parental.title') }}</h1>
      </div>
      <div v-if="selectedProfile" class="parental-page__profile-badge">
        <Icon name="user" size="sm" />
        {{ selectedProfile.name }}
        <Badge tone="neutral">{{ RATING_LABELS[selectedProfile.rating] ?? 'Unknown' }}</Badge>
      </div>
      <!--
        The identity could not be established (S203). Never render nothing here:
        an absent badge is indistinguishable from a page that simply has no badge,
        and the admin would go on editing without knowing whose limits these are.
      -->
      <div
        v-else-if="selectedProfileId && !loadingProfiles"
        class="parental-page__profile-badge parental-page__profile-badge--unknown"
        role="status"
      >
        <Icon name="alert" size="sm" />
        Unidentified profile #{{ selectedProfileId }}
        <Badge tone="error">{{ profilesError ?? 'Not found' }}</Badge>
      </div>
    </header>

    <div v-if="!selectedProfileId" class="parental-page__no-profile">
      <EmptyState
        icon="user"
        :title="t('parental.noProfileSelected')"
        :description="t('parental.noProfileSelectedHint')"
      />
    </div>

    <template v-else>
      <Tabs v-model="activeTab" :tabs="TABS" :label="'Parental control sections'" @update:model-value="handleTabChange">
        <!-- SCHEDULES TAB -->
        <template #schedules>
          <div class="parental-section">
            <div class="parental-section__toolbar">
              <p class="parental-section__hint">
                <kbd>c</kbd> create &nbsp; <kbd>E</kbd> edit &nbsp; <kbd>x</kbd> delete &nbsp; <kbd>r</kbd> refresh
              </p>
              <Button variant="solid" size="sm" left-icon="plus" @click="openScheduleCreate">
                {{ t('parental.createSchedule') }}
              </Button>
            </div>

            <div v-if="loadingSchedules" class="parental-section__loading">
              <Skeleton variant="text" :lines="6" />
            </div>

            <EmptyState
              v-else-if="schedulesError"
              icon="alert"
              :title="t('parental.loadErrorSchedulesTitle')"
              :description="schedulesError"
            >
              <template #actions>
                <Button variant="ghost" size="sm" left-icon="rewind" @click="loadSchedules">{{ t('parental.retry') }}</Button>
              </template>
            </EmptyState>

            <EmptyState
              v-else-if="schedules.length === 0"
              icon="calendar"
              :title="t('parental.noSchedules')"
              :description="t('parental.noSchedulesHint')"
            />

            <div v-else class="parental-section__list">
              <div
                v-for="(schedule, idx) in schedules"
                :key="schedule.id"
                class="parental-section__item"
                :class="{ 'is-selected': idx === selectedScheduleIndex }"
                @click="selectedScheduleIndex = idx"
              >
                <div class="parental-section__item-main">
                  <span class="parental-section__item-name">{{ schedule.name }}</span>
                  <span class="parental-section__item-meta">
                    {{ schedule.start_time.substring(0, 5) }} – {{ schedule.end_time.substring(0, 5) }}
                    &nbsp;·&nbsp;
                    {{ formatDays(schedule.days_of_week) }}
                  </span>
                </div>
                <div class="parental-section__item-actions">
                  <Badge :tone="schedule.is_active ? 'success' : 'neutral'">
                    {{ schedule.is_active ? t('parental.active') : t('parental.inactive') }}
                  </Badge>
                  <Button variant="ghost" size="sm" @click.stop="openScheduleEdit(schedule)">Edit</Button>
                  <Button variant="ghost" size="sm" @click.stop="askDeleteSchedule(schedule)">Delete</Button>
                </div>
              </div>
            </div>
          </div>
        </template>

        <!-- TAGS TAB -->
        <template #tags>
          <div class="parental-section">
            <div class="parental-section__toolbar">
              <p class="parental-section__hint"><kbd>c</kbd> create &nbsp; <kbd>x</kbd> delete &nbsp; <kbd>r</kbd> refresh</p>
              <Button variant="solid" size="sm" left-icon="plus" @click="openTagCreate">
                {{ t('parental.addTag') }}
